from collections import deque

queue = deque()
completed = set()

def enqueue(key, limit=2):
    if key in completed or key in queue:
        return {'status': 'duplicate'}
    if len(queue) >= limit:
        return {'status': 'busy'}
    queue.append(key)
    return {'status': 'queued'}

def worker_once():
    key = queue.popleft()
    completed.add(key)
    return {'status': 'completed', 'key': key}

assert enqueue('ana:2026-10-02')['status'] == 'queued'
assert enqueue('ana:2026-10-02')['status'] == 'duplicate'
assert worker_once()['status'] == 'completed'
